DRIVER_SHA='3abe44b79a4e990be515616af4778ad822132cde1716e688ea646c17caa162e4'
RUNTIME_SHA='66a1746d492103c13d8a6a6ccce45b71fcfd82a8aeceb8d77ecda693bf53e1c0'

def store(folder,name,data):
    path=folder/name
    if path.is_symlink():raise ValueError('工具缓存文件是链接。')
    if path.exists():
        if path.read_bytes()!=data:raise ValueError('同指纹工具内容异常，未覆盖。')
        return path
    with tempfile.NamedTemporaryFile(dir=folder,delete=False) as handle:temporary=Path(handle.name);handle.write(data)
    try:temporary.replace(path)
    finally:temporary.unlink(missing_ok=True)
    return path


def start(root):
    root=Path(root).resolve()
    if sys.platform!='win32':raise ValueError('请在原Windows上传电脑的PowerShell窗口运行。')
    if not (root/'upload_config.json').is_file() or not (root/'.venv/Scripts/python.exe').is_file():raise ValueError('原上传配置或后台Python缺失。')
    updates=download()
    if hashlib.sha256(DRIVER).hexdigest()!=DRIVER_SHA:raise ValueError('今天发布工具校验失败。')
    ast.parse(DRIVER.decode('utf-8'));updates.update({DRIVER_NAME:DRIVER,QUEUE_NAME:QUEUE})
    folder=root/'material-staging/tools'/RUNTIME_SHA[:16]
    for item in (root/'material-staging',root/'material-staging/tools',folder):
        if item.is_symlink() or (hasattr(item,'is_junction') and item.is_junction()):raise ValueError('工具缓存目录是链接。')
        item.mkdir(exist_ok=True)
    for name,data in updates.items():store(folder,name,data)
    manifest={name:hashlib.sha256(data).hexdigest() for name,data in updates.items()}
    store(folder,'runtime-sha256.json',json.dumps(manifest,sort_keys=True).encode('ascii'))
    check=VERIFY+";import publish_eligible60_real_20261123 as n;assert n.VERSION=='1.1-nov23-console-isolated-file-log-background' and n.DAY=='2026-11-23' and n.CONTENT_SHA=='ef039935845a6c85c37d4502d113bf15605f5103e374b0cecff29c32cf9bd894'"
    subprocess.run([sys.executable,'-c',check,str(folder),str(root)],check=True)
    process=subprocess.Popen(['powershell.exe','-NoProfile','-NonInteractive','-WindowStyle','Hidden','-ExecutionPolicy','Bypass','-File',str(folder/QUEUE_NAME),'-Root',str(root),'-Entry',str(folder/DRIVER_NAME),'-EntrySha',DRIVER_SHA],stdout=subprocess.DEVNULL,stderr=subprocess.DEVNULL,creationflags=0x00000208)
    status_path=root/'logs/eligible60-2026-11-23-queue.json'
    for _ in range(100):
        try:status=json.loads(status_path.read_text(encoding='utf-8-sig'))
        except (OSError,ValueError):status={}
        if status.get('pid')==process.pid:
            if status.get('phase')=='error':raise RuntimeError(status.get('message','后台队列启动失败。'))
            print('11月23日任务已进入后台队列：'+status.get('message','等待开始。'),flush=True)
            print('原任务结束且今天分配完成后自动发布；已确认全部实拍，AI关闭，沿用原文案和评论。进度：'+str(root/'logs/eligible60-2026-11-23-run.log'),flush=True)
            return 0
        if process.poll() is not None:
            if process.returncode==0 and status.get('phase') in {'waiting_workers','waiting_distribution','starting'}:
                print('已有今天的后台队列或发布任务，保留原队列，不重复启动。',flush=True);return 0
            raise RuntimeError('后台队列未确认启动，请查看logs/eligible60-2026-11-23-queue.log；没有修改发布记录。')
        time.sleep(.1)
    print('后台等待进程已启动，PID：'+str(process.pid)+'；当前状态见 '+str(status_path),flush=True)
    return 0


